samples.guides/client-credentials:
const wf = await Wefunder.fromClientCredentials({
  clientId: process.env.WEFUNDER_CLIENT_ID!,
  clientSecret: process.env.WEFUNDER_CLIENT_SECRET!,
  scopes: ["read:public"],
});

console.log("mode:", wf.mode); // "live" or "test", from the token prefix

// client_credentials holds only read:public — browse public offerings.
// (wf.users.me() would throw 403 insufficient_scope: it needs read:profile.)
for await (const offering of wf.offerings.all()) {
  console.log(offering.id);
}

samples.listActivity:
// Everything my connected apps did to syndicate members, most recent first.
const activity = await wf.unwrap(
  wf.raw.listActivity({
    query: { action_pattern: "syndicates.member.*", status: "success" },
  }),
);
for (const event of activity.data ?? []) {
  console.log(event.attributes?.action, event.attributes?.created_at);
}

samples.listAttributedInvestments:
const investments = await wf.unwrap(
  wf.raw.listAttributedInvestments({
    path: { campaign_id: 1234 },
    query: { start_date: "2026-01-01", detail_level: "anonymized" },
  }),
);
for (const investment of investments.data ?? []) {
  if ("amount_tier" in investment) {
    // Anonymized row: opaque tokens + an amount tier, never exact values or PII.
    console.log(investment.investor_token, investment.amount_tier, investment.attribution?.utm_source);
  }
}

samples.listCampaigns:
// Campaigns for companies where the authenticated user is a founder.
const page = await wf.campaigns.list();
for (const campaign of page.data ?? []) {
  console.log(campaign.id, campaign.attributes?.company_name, campaign.attributes?.amount_raised);
}

// Or stream every campaign lazily, one page fetched at a time:
for await (const campaign of wf.campaigns.all()) {
  console.log(campaign.attributes?.state);
}

samples.listConnectedApps:
const apps = await wf.unwrap(wf.raw.listConnectedApps());
for (const app of apps.data ?? []) {
  console.log(app.id, app.attributes?.name);
}

samples.listIntents:
// Which of my proposed actions are still waiting on human approval?
const page = await wf.intents.list({ status: "pending" });
for (const intent of page.data ?? []) {
  console.log(intent.id, intent.attributes?.action, intent.attributes?.review_url);
}

samples.listInvestments:
// Auto-paginate the full history lazily:
for await (const investment of wf.investments.all()) {
  console.log(investment.id);
}

// Or grab one page with its meta (next_cursor, etc.):
const page = await wf.investments.list();
console.log(page.data?.length, page.meta?.next_cursor);

samples.listOfferings:
// Browse live offerings, sorted. The cursor is opaque and handled for you.
const page = await wf.offerings.list({ sort: "most_raised" });
for (const offering of page.data ?? []) {
  console.log(offering.id, offering.attributes?.company_name);
}

// Or stream every offering lazily, one page fetched at a time:
for await (const offering of wf.offerings.all({ sort: "newest" })) {
  console.log(offering.id);
}

samples.listSyndicates:
const page = await wf.syndicates.list({ limit: 50 });
for (const syndicate of page.data ?? []) {
